diff --git a/index.js b/index.js
index 5ecd392..eab5164 100644
--- a/index.js
+++ b/index.js
@@ -47,15 +47,13 @@ export default function pLimit(concurrency) {
 		next();
 	};

-	const enqueue = (function_, resolve, reject, arguments_) => {
-		const queueItem = {reject};
-
+	const enqueue = (function_, queueItem, arguments_) => {
 		// Queue the internal resolve function instead of the run function
 		// to preserve the asynchronous execution context.
 		new Promise(internalResolve => { // eslint-disable-line promise/param-names
 			queueItem.run = internalResolve;
 			queue.enqueue(queueItem);
-		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then
+		}).then(run.bind(undefined, function_, queueItem.resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then

 		// Start processing immediately if we haven't reached the concurrency limit
 		if (activeCount < concurrency) {
@@ -63,9 +61,13 @@ export default function pLimit(concurrency) {
 		}
 	};

-	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
-		enqueue(function_, resolve, reject, arguments_);
-	});
+	const generator = (function_, ...arguments_) => {
+		const promise = new Promise((resolve, reject) => {
+			enqueue(function_, {resolve, reject, getPromise: () => promise}, arguments_);
+		});
+
+		return promise;
+	};

 	Object.defineProperties(generator, {
 		activeCount: {
@@ -84,7 +86,12 @@ export default function pLimit(concurrency) {
 				const abortError = AbortSignal.abort().reason;

 				while (queue.size > 0) {
-					queue.dequeue().reject(abortError);
+					const queueItem = queue.dequeue();
+					queueItem.reject(abortError);
+					// Guard against unhandled rejection warnings if the caller
+					// hasn't attached a handler yet; their own await/then/catch
+					// on the returned promise still receives the rejection.
+					queueItem.getPromise().catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
 				}
 			},
 		},
